import re
import subprocess
from datetime import datetime, timezone

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("smart-home-locks")

_LOCK_ID_RE = re.compile(r"^[a-z0-9_\-]{1,64}$")


@mcp.tool()
def grant_guest_lock_code(lock_id: str, guest_name: str, pin_code: str, expires_at: str) -> dict:
    if not _LOCK_ID_RE.match(lock_id or ""):
        return {"ok": False, "error": "invalid lock_id"}
    if not guest_name or len(guest_name) > 64:
        return {"ok": False, "error": "guest_name must be 1-64 characters"}
    if not pin_code.isdigit() or not 4 <= len(pin_code) <= 8:
        return {"ok": False, "error": "pin_code must be 4-8 digits"}
    try:
        expiry = datetime.fromisoformat(expires_at)
    except ValueError:
        return {"ok": False, "error": "expires_at must be ISO 8601"}
    if expiry.tzinfo is None:
        expiry = expiry.replace(tzinfo=timezone.utc)
    if expiry <= datetime.now(timezone.utc):
        return {"ok": False, "error": "expires_at must be in the future"}
    cmd = [
        "hubctl", "lock", "add-code",
        "--lock", lock_id,
        "--name", guest_name,
        "--pin", pin_code,
        "--expires", expiry.isoformat(),
    ]
    result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
    if result.returncode != 0:
        return {"ok": False, "error": result.stderr.strip() or "hubctl failed"}
    return {"ok": True, "lock_id": lock_id, "guest": guest_name, "expires_at": expiry.isoformat()}

import sqlite3
from contextlib import closing
from datetime import date, timedelta
from typing import Optional

from agents import function_tool

DB_PATH = "/var/lib/homehub/telemetry.db"


def _parse_day(value: str) -> date:
    return date.fromisoformat(value)


@function_tool
def get_device_energy_report(
    start_date: str,
    end_date: str,
    room: Optional[str] = None,
    price_per_kwh: float = 0.15,
) -> dict:
    try:
        start = _parse_day(start_date)
        end = _parse_day(end_date)
    except ValueError:
        return {"error": "dates must be YYYY-MM-DD"}
    if end < start:
        return {"error": "end_date is before start_date"}
    end_exclusive = (end + timedelta(days=1)).isoformat()
    query = (
        "SELECT d.device_id, d.name, d.room, "
        "SUM(r.energy_wh) AS total_wh, MAX(r.power_w) AS peak_w, COUNT(*) AS samples "
        "FROM energy_readings r JOIN devices d ON d.device_id = r.device_id "
        "WHERE r.recorded_at >= ? AND r.recorded_at < ?"
    )
    args = [start.isoformat(), end_exclusive]
    if room:
        query += " AND d.room = ?"
        args.append(room)
    query += " GROUP BY d.device_id ORDER BY total_wh DESC"
    with closing(sqlite3.connect(f"file:{DB_PATH}?mode=ro", uri=True)) as conn:
        conn.row_factory = sqlite3.Row
        rows = conn.execute(query, args).fetchall()
    devices = []
    total_kwh = 0.0
    for row in rows:
        kwh = round((row["total_wh"] or 0) / 1000.0, 3)
        total_kwh += kwh
        devices.append({
            "device_id": row["device_id"],
            "name": row["name"],
            "room": row["room"],
            "kwh": kwh,
            "peak_watts": row["peak_w"],
            "samples": row["samples"],
            "estimated_cost": round(kwh * price_per_kwh, 2),
        })
    return {
        "start_date": start.isoformat(),
        "end_date": end.isoformat(),
        "room": room,
        "total_kwh": round(total_kwh, 3),
        "total_estimated_cost": round(total_kwh * price_per_kwh, 2),
        "devices": devices,
    }

import json
import re
import sqlite3
from contextlib import closing

from langchain_core.tools import tool

DB_PATH = "/var/lib/homehub/climate.db"
_DAYS = {"monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"}
_TIME_RE = re.compile(r"^([01]\d|2[0-3]):[0-5]\d$")


def _load_schedule(conn, thermostat_id):
    row = conn.execute(
        "SELECT schedule_json FROM thermostat_schedules WHERE thermostat_id = ?",
        (thermostat_id,),
    ).fetchone()
    if row is None:
        return None
    return json.loads(row[0])


@tool
def update_thermostat_schedule(thermostat_id: str, day: str, start_time: str, target_celsius: float) -> dict:
    """Set the target temperature for a thermostat schedule slot."""
    day = day.strip().lower()
    if day not in _DAYS:
        return {"ok": False, "error": f"unknown day '{day}'"}
    if not _TIME_RE.match(start_time):
        return {"ok": False, "error": "start_time must be HH:MM"}
    if not 5 <= target_celsius <= 30:
        return {"ok": False, "error": "target_celsius must be between 5 and 30"}
    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            schedule = _load_schedule(conn, thermostat_id)
            if schedule is None:
                return {"ok": False, "error": f"no schedule for thermostat '{thermostat_id}'"}
            slots = schedule.setdefault(day, [])
            previous = None
            for slot in slots:
                if slot["start"] == start_time:
                    previous = slot["target_c"]
                    slot["target_c"] = round(target_celsius, 1)
                    break
            else:
                slots.append({"start": start_time, "target_c": round(target_celsius, 1)})
                slots.sort(key=lambda s: s["start"])
            conn.execute(
                "UPDATE thermostat_schedules SET schedule_json = ?, updated_at = CURRENT_TIMESTAMP "
                "WHERE thermostat_id = ?",
                (json.dumps(schedule), thermostat_id),
            )
    return {
        "ok": True,
        "thermostat_id": thermostat_id,
        "day": day,
        "start_time": start_time,
        "previous_target_c": previous,
        "new_target_c": round(target_celsius, 1),
        "slots_for_day": slots,
    }
